export const MONUMENTS = JSON.parse("[{\"id\":\"n8634928239\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Возвращение из эмиграции В. И. Ленина\",\"x\":276.2,\"z\":-2722.6,\"inscription\":\"Здесь, на площади, 3 (16) апреля 1917 года рабочие Петрограда, солдаты и матросы восторженно встречали возвратившегося из эмиграции В.И. Ленина. В.И. с броневика приветствовал революционный пролетариат и революционную армию с победой над царизмом и ...\"},{\"id\":\"n13787262859\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":286.5,\"z\":-2698.2,\"inscription\":\"1870 была открыта железная дорога Рихимяки - Ленинград (Петербург)\\n1870 Valmistui Riihimaen - Leningradin (Pietarin) Rautatie\\n11.9.1970 Город Рихимяки\\nRiihimäen Kaupunki\"},{\"id\":\"n4269363591\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Поцелуй\",\"x\":169.1,\"z\":-2698.8,\"artist\":\"Антонина Фатхуллина\"},{\"id\":\"n5078731218\",\"kind\":\"artwork\",\"sub\":\"architecture\",\"name\":\"Доходный дом Опочининой\",\"x\":152.4,\"z\":-2722.5,\"startDate\":\"1875\",\"subject\":\"Q4484922\",\"artist\":\"А. Д. Шиллинг\",\"description\":\"1875 - арх. Шиллинг Александр Дмитриевич (акад. арх.)\\nПятиэтажный жилой дом с торговыми помещениями в первом этаже. Нарядно декорированный фасад, энергично рустованный, с несколько вычурным эркером на консолях со львами в середине третьего этажа. \"},{\"id\":\"n11766388980\",\"kind\":\"artwork\",\"sub\":\"relief\",\"name\":\"Магический квадрат\",\"x\":111.6,\"z\":-2729.5,\"subject\":\"Q192089\"}]");
